function renderAll() {
  renderPeriodStatus();
  renderDashboard();
  renderRegister();
  renderDepreciation();
  renderReconciliation();
  renderRetired();
  renderReports();
  renderCip();
}
function renderPeriodStatus() {
  const last = lastPostedPeriod(S.currentFund);
  document.getElementById("periodStatus").textContent =
    "Baseline " + periodShort(BASELINE_PERIOD) + (last ? " • Posted through " + periodShort(last) : " • No postings yet");
}
const VIEW_TITLES = {
  dashboard: ["Dashboard", "Straight-line PPE depreciation"],
  register: ["Asset Register", "Property card for every PPE item — cost, residual value, useful life"],
  depreciation: ["Monthly Depreciation", "Compute, post, and generate the JEV summary for a period"],
  reconciliation: ["Reconciliation", "Compare the register against your Trial Balance, by account code"],
  retired: ["Retired Assets", "Derecognized / disposed items kept for historical reference"],
  reports: ["Reports", "Generate the Equipment Ledger Card and Property Card for any asset"],
  cip: ["Construction in Progress", "Track CIP projects and their billings, separate from the Asset Register, until each is completed and transferred to PPE"],
};
/** Sets the topbar title/subtitle from the current view + fund. Called on both view changes and
 *  fund switches, since the subtitle always names which fund's books are showing. */
function refreshTopbar() {
  const t = VIEW_TITLES[S.view];
  document.getElementById("viewTitle").textContent = t[0];
  document.getElementById("viewSubtitle").textContent = t[1] + " • " + fundLabel(S.currentFund);
}
function setView(v) {
  S.view = v;
  document.querySelectorAll("#nav button").forEach(b => b.classList.toggle("active", b.dataset.view === v));
  document.querySelectorAll(".view").forEach(el => el.classList.toggle("active", el.id === "view-" + v));
  refreshTopbar();
}
/** Switches which fund's books are in view. Every render function reads S.currentFund, so this is
 *  the one place that needs to re-render everything; period selections are cleared since a period
 *  chosen for one fund's Monthly Depreciation / Reconciliation may not be meaningful for another. */
function setFund(fund) {
  if (!FUNDS.some(f => f.code === fund) || fund === S.currentFund) return;
  S.currentFund = fund;
  try { localStorage.setItem("ppeFund", fund); } catch (e) { /* private browsing, etc. — fine to skip */ }
  document.querySelectorAll("#fundSwitch button").forEach(b => b.classList.toggle("active", b.dataset.fund === fund));
  S.depPeriod = null;
  S.reconPeriod = null;
  refreshTopbar();
  renderAll();
}

/* ---------- modal helpers ---------- */
function openModal(html) {
  document.getElementById("modalRoot").innerHTML = html;
  document.getElementById("modalOverlay").classList.add("open");
}
function closeModal() { document.getElementById("modalOverlay").classList.remove("open"); }

/* ---------- static UI wiring (nav buttons, fund switcher, modal overlay) — bound once ---------- */
let staticUiBound = false;
function bindStaticUI() {
  if (staticUiBound) return;
  staticUiBound = true;
  document.querySelectorAll("#nav button").forEach(b => b.addEventListener("click", () => setView(b.dataset.view)));
  document.querySelectorAll("#fundSwitch button").forEach(b => b.addEventListener("click", () => setFund(b.dataset.fund)));
  const overlay = document.getElementById("modalOverlay");
  if (overlay) overlay.addEventListener("click", e => { if (e.target.id === "modalOverlay") closeModal(); });
}

/* ---------- entry point, called by js/main.js once Firebase Auth confirms a signed-in user ---------- */
export function initApp(user) {
  S.currentUser = user;
  try {
    const saved = localStorage.getItem("ppeFund");
    if (saved && FUNDS.some(f => f.code === saved)) S.currentFund = saved;
  } catch (e) { /* private browsing, etc. — fine to skip, defaults to GF */ }
  document.querySelectorAll("#fundSwitch button").forEach(b => b.classList.toggle("active", b.dataset.fund === S.currentFund));
  const emailEl = document.getElementById("authEmail");
  if (emailEl) emailEl.textContent = viewerLabel();
  bindStaticUI();
  setView(S.view);
  initDb();
  renderAll();
}

/* ---------- expose functions referenced from inline onclick="" handlers in rendered HTML ----------
   (ES module top-level declarations are NOT added to `window` automatically, unlike classic scripts,
   so anything called from an inline event handler attribute must be attached explicitly.) */
